e,$role,$active,(int)$row['user_id']]);respond(['ok'=>true,'message'=>'Đã cập nhật tài khoản.']);}if($m==='PATCH'){$username=trim((string)($d['username']??''));if($username===''||$username==='admin')respond(['ok'=>false,'message'=>'Không thể khóa tài khoản Admin mặc định.'],422);$pdo->prepare('UPDATE users SET active=IF(active=1,0,1) WHERE username=?')->execute([$username]);respond(['ok'=>true,'message'=>'Đã thay đổi trạng thái tài khoản.']);}if($m==='DELETE'){$username=trim((string)($_GET['username']??''));if($username===''||$username==='admin')respond(['ok'=>false,'message'=>'Không thể xóa tài khoản này.'],422);$pdo->prepare('DELETE FROM users WHERE username=?')->execute([$username]);respond(['ok'=>true,'message'=>'Đã xóa tài khoản.']);}respond(['ok'=>false,'message'=>'Phương thức không được hỗ trợ.'],405);}catch(PDOException $e){error_log($e->__toString());$msg=$e->getCode()==='23000'?'Tên đăng nhập hoặc email đã tồn tại.':'Không thể cập nhật tài khoản.';respond(['ok'=>false,'message'=>$msg],409);}catch(Throwable $e){error_log($e->__toString());respond(['ok'=>false,'message'=>'Không thể cập nhật tài khoản.'],500);}
